alters.statement:
ALTER TABLE public.clientes
  ADD COLUMN IF NOT EXISTS pontos numeric(14,2) NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS saldo_carteira numeric(14,2) NOT NULL DEFAULT 0;

ALTER TABLE public.faturas
  ADD COLUMN IF NOT EXISTS orcamento_id uuid REFERENCES public.orcamentos(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS desconto_promocional_aplicado numeric NOT NULL DEFAULT 0;

ALTER TABLE public.ordens_assinatura
  ADD COLUMN IF NOT EXISTS nome_assinatura_contratada TEXT,
  ADD COLUMN IF NOT EXISTS valor_mensal_contratado NUMERIC;

ALTER TABLE public.orcamentos
    ADD COLUMN subtotal_preco_tabela numeric NULL,
    ADD COLUMN desconto_produtos numeric NULL;
